/**
 * Photography catalogue.
 * - Titles, autogenerated alt descriptions and promotional taglines are intentionally absent.
 * - Only actual places, dates and the photographer's own captions are shown.
 * - New captions come from the photographer’s edited Numbers worksheet.
 * - Files are discovered automatically from src/assets/photos, supporting WebP, JPG and JPEG.
 */
export const themes = [
  'Weather & light',
  'Water & mountains',
  'Paths & seasons',
  'Cities & evenings',
  'Other',
] as const;
export type PhotoTheme = (typeof themes)[number];

