export type PhotoSeries = keyof typeof seriesNotes;

export interface Photo {
  id: string;
  theme: PhotoTheme;
  region: string | null;
  place: string | null;
  taken: string | null;
  caption: string | null;
  series: PhotoSeries | null;
  src: string;
  thumbSrc: string;
}

type Notes = {
  theme: PhotoTheme;
  region?: string;
  place?: string;
  taken?: string;
  caption?: string;
  series?: PhotoSeries;
};

