const originalFiles = import.meta.glob([
  '../assets/photos/*.{webp,WebP,jpg,JPG,jpeg,JPEG}',
  '!../assets/photos/converted-12.webp',
  '!../assets/photos/IMG_1478.webp',
], {
  eager: true,
  query: '?url',
  import: 'default',
}) as Record<string, string>;

const thumbnailFiles = import.meta.glob('../assets/photos/thumbs/*.{webp,WebP,jpg,JPG,jpeg,JPEG}', {
  eager: true,
  query: '?url',
  import: 'default',
}) as Record<string, string>;

// Converted filenames from the earlier batch, visually matched to their originals.
const convertedNameToOriginal: Record<string, string> = {
  'converted': 'IMG_0648',
  'converted-2': 'IMG_0669',
  'converted-3': 'IMG_0718',
  'converted-4': 'IMG_0720',
  'converted-5': 'IMG_0722',
  'converted-6': 'IMG_0724',
  // converted-7 is a separate image
  'converted-8': 'IMG_0766',
  'converted-9': 'IMG_0979',
  'converted-10': 'IMG_1475',
  'converted-11': 'IMG_1477',
  'converted-13': 'IMG_1783',
  'converted-14': 'IMG_1964',
  'converted-15': 'IMG_2045',
  'converted-16': 'IMG_2046',
  'converted-17': 'IMG_2112',
  'converted-18': 'IMG_2169',
  'converted-19': 'IMG_2172',
};

function photoId(path: string): string {
  const filename = path.split('/').pop() ?? path;
  const rawStem = filename.replace(/\.(webp|jpe?g)$/i, '');
  return convertedNameToOriginal[rawStem] ?? rawStem;
}

const thumbsById = new Map(
  Object.entries(thumbnailFiles).map(([path, url]) => [photoId(path), url])
);

// Prefer a WebP over a JPEG when both copies have the same name.
const orderedFiles = Object.entries(originalFiles)
  .filter(([path]) => !excludedStems.has((path.split('/').pop() ?? '').replace(/\.(webp|jpe?g)$/i, '')))
  .sort(([a], [b]) => {
  const priority = (path: string) => /\.webp$/i.test(path) ? 0 : 1;
  return priority(a) - priority(b);
});
const seen = new Set<string>();
export const photos: Photo[] = orderedFiles.flatMap(([path, url]) => {
  const id = photoId(path);
  if (seen.has(id)) return [];
  seen.add(id);
  const note = details[id];
  return [{
    id,
    src: url,
    thumbSrc: thumbsById.get(id) ?? url,
    theme: note?.theme ?? 'Other',
    region: note?.region ?? null,
    place: note?.place ?? null,
    taken: note?.taken ?? null,
    caption: note?.caption ?? null,
    series: note?.series ?? null,
  }];
}).sort((a,b) => {
  const ai = featuredIds.indexOf(a.id), bi = featuredIds.indexOf(b.id);
  if (ai >= 0 || bi >= 0) {
    if (ai < 0) return 1;
    if (bi < 0) return -1;
    return ai-bi;
  }
  return (a.place || '').localeCompare(b.place || '') || a.id.localeCompare(b.id);
});

export const selectedPhotos = () => featuredIds
  .map((id) => photos.find((photo) => photo.id === id))
  .filter((photo): photo is Photo => photo !== undefined);

export const imagePath = (photo: Photo) => photo.src;
export const thumbnailPath = (photo: Photo) => photo.thumbSrc;

/** Only photographer-authored prose. Never return invented scene descriptions. */
export const captionForPhoto = (photo: Photo): string | null =>
  photo.caption ?? (photo.series ? seriesNotes[photo.series].text : null);
